        Quest("CH1-052",1,52,"The Experiment",category="Khorinis - Harbor District",giver="Nadja / Bromor",location="Khorinis - Harbor District",prerequisites="Chapter 1; pay Bromor or complete Bromor's Golden Vase.",summary="Arrange a night with Nadja at the Red Lantern.",walkthroughSteps=listOf("Arrange a night with Nadja at the Red Lantern. Pay the normal fee, or first return Bromor's stolen golden vase to obtain the encounter for free. Follow Nadja upstairs and complete her dialogue."),reward="350 XP and +10 stamina.",warnings="Doing Bromor's quest first avoids the 50-gold fee.",searchTags=listOf("the experiment","khorinis - harbor district","nadja / bromor")),
        Quest("CH1-053",1,53,"Man in the Guise of a Beast",category="Khorinis - Harbor District",giver="Ignaz",location="Khorinis - Harbor District",prerequisites="Finish Ignaz's Experiment quest.",summary="Reverse an experiment that transformed Ignaz's apprentice into a beast.",walkthroughSteps=listOf("After completing Experiment, ask Ignaz about his missing apprentice.","Investigate by speaking to Mika, Akil, Orlan, and Sagitta in that order.","When the transformed apprentice appears near Sagitta, visit Vatras for a scroll that can restore its mind.","Return to Sagitta's cave, speak to her and use the scroll near the shadowbeast.","Speak with Sagitta again and return to Ignaz for your reward."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="This is an index-guided quick solution. Exact item counts, coordinates and reward values can differ with New Balance updates; use the linked source record when a build-specific detail matters.",searchTags=listOf("man in the guise of a beast","khorinis - harbor district","local quest giver in khorinis - harbor district","ignaz")),
